const rawInput = $input.first().json.body || $input.first().json || {};
const rawFrom = rawInput.from;
const rawMensagem = rawInput.mensagem;

if (!rawFrom || !rawMensagem || typeof rawMensagem !== 'string' || rawMensagem.trim().length === 0) {
  return [{ json: { isValid: false, errorCode: 'INVALID_PAYLOAD', errorMessage: "Os campos 'from' e 'mensagem' sao obrigatorios.", received: rawInput } }];
}

const usuario = String(rawFrom).replace(/\D/g, '') || String(rawFrom).trim();

return [{ json: { isValid: true, usuario, mensagemOriginal: rawMensagem.trim(), receivedAt: new Date().toISOString() } }];

const mensagem = $json.mensagemOriginal;
const body = {
  model: "gpt-4o-mini",
  temperature: 0.2,
  response_format: { type: "json_object" },
  messages: [
    {
      role: "system",
      content: "Voc\u00ea \u00e9 a IA de triagem e atendimento da Profissionais S.A. (PSA), a maior curadoria de palestras e especialistas do Brasil ('Aprender \u00e9 o maior Show da Terra'). A PSA atende dois grandes p\u00fablicos: 1) B2B (Empresas, RHs e Organizadores): contrata\u00e7\u00e3o de palestrantes para conven\u00e7\u00f5es, SIPAT, eventos corporativos, lideran\u00e7a, inova\u00e7\u00e3o, vendas e IA. 2) B2C (Especialistas, Autores e Executivos): forma\u00e7\u00e3o e curadoria de carreira para palestrantes atrav\u00e9s da 'The Best School' e programas de imers\u00e3o para subir aos palcos. Al\u00e9m disso, h\u00e1 o suporte operacional a eventos em andamento (log\u00edstica, rider t\u00e9cnico, imprevistos de agenda) e d\u00favidas institucionais. Analise a mensagem recebida e classifique estritamente em uma das 4 inten\u00e7\u00f5es: - B2B_CONTRATAR_PALESTRANTE: Empresas buscando palestrantes, or\u00e7amentos, cat\u00e1logo de especialistas, temas corporativos ou cota\u00e7\u00e3o para conven\u00e7\u00f5es. - B2C_QUERO_SER_PALESTRANTE: Especialistas querendo virar palestrante, The Best School, imers\u00e3o de palestrantes, mentoria de carreira, entrar no casting. - SUPORTE_EVENTO_URGENTE: Problemas operacionais com eventos de hoje/amanh\u00e3, altera\u00e7\u00e3o urgente de agenda, voos, log\u00edstica ou alinhamento t\u00e9cnico do palco. - INSTITUCIONAL_DUVIDAS: D\u00favidas gerais, acesso \u00e0 \u00e1rea de login, blog/conte\u00fados, quem somos e contatos da PSA. Responda EXCLUSIVAMENTE em formato JSON com o schema: {\"intencao\": string, \"confianca\": number, \"resumo\": string, \"resposta\": string}. No campo 'resposta', seja emp\u00e1tico, \u00e1gil, altamente profissional e acolhedor em portugu\u00eas, representando a marca PSA."
    },
    {
      role: "user",
      content: mensagem
    }
  ]
};
return [{ json: { ...($json), openaiBody: JSON.stringify(body) } }];

const httpResp = $input.first().json;
let aiResult = {};
try {
  const raw = httpResp.choices[0].message.content;
  aiResult = JSON.parse(raw);
} catch(e) {
  aiResult = { intencao: 'DUVIDA_GERAL', confianca: 0.5, resumo: 'Falha ao parsear IA', resposta: 'Mensagem recebida. Em breve entraremos em contato.' };
}

const validado = $('Code - Validacao Defensiva').first().json;

return [{ json: { usuario: validado.usuario, mensagemOriginal: validado.mensagemOriginal, resposta: aiResult.resposta, intencao: aiResult.intencao, confianca: aiResult.confianca, resumo: aiResult.resumo, motor: 'openai/gpt-4o-mini', receivedAt: validado.receivedAt, processedAt: new Date().toISOString() } }];
